previewCss:
.darma-loader-darma-b15-sand-dune-drift { --accent: var(--loader-color, #d97706); --accent-2: var(--loader-secondary-color, #fde68a); width: var(--loader-size, 130px); height: calc(var(--loader-size, 130px) * .58); position: relative; overflow: hidden; border-radius: 8px; background: color-mix(in srgb, var(--accent-2) 22%, transparent); }
.darma-loader-darma-b15-sand-dune-drift span { position: absolute; left: -22%; width: 144%; border-radius: 50% 50% 0 0 / 100% 100% 0 0; animation: darma-loader-darma-b15-sand-dune-drift-dune-drift calc(var(--loader-speed, 1s) * 7) linear infinite; }
.darma-loader-darma-b15-sand-dune-drift span:nth-of-type(1) { bottom: 0; height: 52%; background: var(--accent); }
.darma-loader-darma-b15-sand-dune-drift span:nth-of-type(2) { bottom: 0; height: 38%; background: color-mix(in srgb, #fff 22%, var(--accent)); animation-duration: calc(var(--loader-speed, 1s) * 5); animation-delay: calc(var(--loader-speed, 1s) * -1.6); }
.darma-loader-darma-b15-sand-dune-drift span:nth-of-type(3) { bottom: 0; height: 24%; background: var(--accent-2); animation-duration: calc(var(--loader-speed, 1s) * 3.4); }
.darma-loader-darma-b15-sand-dune-drift i { position: absolute; width: 5%; height: 5%; border-radius: 50%; background: var(--accent-2); opacity: 0; animation: darma-loader-darma-b15-sand-dune-drift-dune-grain calc(var(--loader-speed, 1s) * 2.4) linear infinite; }
.darma-loader-darma-b15-sand-dune-drift i:nth-of-type(1) { top: 22%; }
.darma-loader-darma-b15-sand-dune-drift i:nth-of-type(2) { top: 40%; animation-delay: calc(var(--loader-speed, 1s) * .8); }
.darma-loader-darma-b15-sand-dune-drift i:nth-of-type(3) { top: 12%; animation-delay: calc(var(--loader-speed, 1s) * 1.6); }
@keyframes darma-loader-darma-b15-sand-dune-drift-dune-drift { 0%, 100% { transform: translateX(-8%); } 50% { transform: translateX(8%); } }
@keyframes darma-loader-darma-b15-sand-dune-drift-dune-grain { 0% { opacity: 0; left: -6%; } 15%, 80% { opacity: .9; } 100% { opacity: 0; left: 104%; } }

